import os
from typing import Dict, Optional, Union

from google.cloud import kms


class GCPEnvelopeEncryptor:
    def __init__(
        self,
        key_name: str,
        project_id: Optional[str] = None,
        location_id: Optional[str] = None,
        key_ring_id: Optional[str] = None,
        crypto_key_id: Optional[str] = None,
    ):
        self.client = kms.KeyManagementServiceClient()
        self.key_name = key_name
        self.project_id = project_id
        self.location_id = location_id
        self.key_ring_id = key_ring_id
        self.crypto_key_id = crypto_key_id

    @classmethod
    def from_env(cls) -> "GCPEnvelopeEncryptor":
        key_name = os.environ["GCP_KMS_KEY_NAME"]
        return cls(key_name=key_name)

    def _kms_key_path(self) -> str:
        if self.key_name:
            return self.key_name

        if not all([self.project_id, self.location_id, self.key_ring_id, self.crypto_key_id]):
            raise ValueError(
                "Either key_name must be provided, or project_id/location_id/key_ring_id/crypto_key_id must all be set."
            )

        return self.client.crypto_key_path(
            self.project_id,
            self.location_id,
            self.key_ring_id,
            self.crypto_key_id,
        )

    def encrypt(self, plaintext: Union[str, bytes]) -> Dict[str, bytes]:
        if isinstance(plaintext, str):
            plaintext_bytes = plaintext.encode("utf-8")
        else:
            plaintext_bytes = plaintext

        key_name = self._kms_key_path()
        response = self.client.encrypt(request={"name": key_name, "plaintext": plaintext_bytes})

        return {
            "ciphertext": response.ciphertext,
            "kms_key_name": key_name.encode("utf-8"),
        }

    def decrypt(self, ciphertext: bytes, key_name: Optional[str] = None) -> bytes:
        kms_key = key_name or self._kms_key_path()
        response = self.client.decrypt(request={"name": kms_key, "ciphertext": ciphertext})
        return response.plaintext


class EnvelopeEncryptionManager:
    def __init__(self, kms_encryptor: GCPEnvelopeEncryptor):
        self.kms_encryptor = kms_encryptor

    def encrypt(self, data: Union[str, bytes]) -> Dict[str, bytes]:
        return self.kms_encryptor.encrypt(data)

    def decrypt(self, encrypted_payload: Dict[str, bytes]) -> bytes:
        ciphertext = encrypted_payload["ciphertext"]
        key_name = encrypted_payload.get("kms_key_name", b"").decode("utf-8") or None
        return self.kms_encryptor.decrypt(ciphertext=ciphertext, key_name=key_name)


def create_envelope_encryption_manager() -> EnvelopeEncryptionManager:
    key_name = os.getenv("GCP_KMS_KEY_NAME")
    project_id = os.getenv("GCP_PROJECT_ID")
    location_id = os.getenv("GCP_KMS_LOCATION_ID")
    key_ring_id = os.getenv("GCP_KMS_KEY_RING_ID")
    crypto_key_id = os.getenv("GCP_KMS_CRYPTO_KEY_ID")

    encryptor = GCPEnvelopeEncryptor(
        key_name=key_name,
        project_id=project_id,
        location_id=location_id,
        key_ring_id=key_ring_id,
        crypto_key_id=crypto_key_id,
    )
    return EnvelopeEncryptionManager(encryptor)
